            SX11 += p * (B01*fx10 + B10*fx01 + B11*fx00 + fx11);
            SX02 += p * (2.0*B01*fx01 + B02*fx00 + fx02);
            SX30 += p * (3.0*B10*fx20 + 3.0*B20*fx10 + B30*fx00 + fx30);
            SX21 += p * (B01*fx20 + 2.0*B10*fx11 + 2.0*B11*fx10 + B20*fx01 + B21*fx00 + fx21);
            SX12 += p * (2.0*B01*fx11 + B02*fx10 + B10*fx02 + 2.0*B11*fx01 + B12*fx00 + fx12);
