    double R41 = 0.0;
    double R42 = 0.0;
    double R43 = 0.0;
    double R44 = 0.0;
    double R50 = 0.0;
    double R51 = 0.0;
    double R52 = 0.0;
    double R53 = 0.0;
    double R54 = 0.0;
    double R55 = 0.0;
    double Rb1 = 0.0;
    double Rb2 = 0.0;
    double Rb3 = 0.0;
    double SA30 = 0.0;
    double SA21 = 0.0;
    double SA12 = 0.0;
    double SA03 = 0.0;
    double SX00 = 0.0;
    double SX10 = 0.0;
    double SX01 = 0.0;
    double SX20 = 0.0;
    double SX11 = 0.0;
    double SX02 = 0.0;
    double SX30 = 0.0;
    double SX21 = 0.0;
    double SX12 = 0.0;
    double SX03 = 0.0;
