        const double fa01 = -2.0*R31;
        const double fa02 = 6.0*R42;
        const double fa03 = -24.0*R53;
        const double fa10 = -2.0*R30;
        const double fa11 = 6.0*R41;
        const double fa12 = -24.0*R52;
        const double fa20 = 6.0*R40;
        const double fa21 = -24.0*R51;
        const double fa30 = -24.0*R50;
        const double fx00 = R22;
        const double fx01 = -2.0*R33;
        const double fx02 = 6.0*R44;
        const double fx03 = -24.0*R55;
        const double fx10 = -2.0*R32;
        const double fx11 = 6.0*R43;
        const double fx12 = -24.0*R54;
        const double fx20 = 6.0*R42;
        const double fx21 = -24.0*R53;
        const double fx30 = -24.0*R52;
