        SA12 += p * (2.0*B01*fa11 + B02*fa10 + B10*fa02 + 2.0*B11*fa01 + B12*fa00 + fa12);
        SA03 += p * (3.0*B01*fa02 + 3.0*B02*fa01 + B03*fa00 + fa03);
