        const double Bb02 = Bb01*t01 + t02;
        const double Bb30 = 2.0*Bb10*t20 + Bb20*t10 + t30;
        const double Bb21 = Bb01*t20 + Bb10*t11 + Bb11*t10 + t21;
        const double Bb12 = 2.0*Bb01*t11 + Bb02*t10 + t12;
        const double Bb03 = 2.0*Bb01*t02 + Bb02*t01 + t03;
