            const double fc10 = -2.0*R31;
            const double fc11 = 6.0*R42;
            const double fc12 = -24.0*R53;
            const double fc20 = 6.0*R41;
            const double fc21 = -24.0*R52;
            const double fc30 = -24.0*R51;
