            const double Lc11 = Bb01*fc10 + Bb10*fc01 + Bb11*fc00 + fc11;
            const double Lc02 = 2.0*Bb01*fc01 + Bb02*fc00 + fc02;
            const double Lc30 = 3.0*Bb10*fc20 + 3.0*Bb20*fc10 + Bb30*fc00 + fc30;
            const double Lc21 = Bb01*fc20 + 2.0*Bb10*fc11 + 2.0*Bb11*fc10 + Bb20*fc01 + Bb21*fc00 + fc21;
            const double Lc12 = 2.0*Bb01*fc11 + Bb02*fc10 + Bb10*fc02 + 2.0*Bb11*fc01 + Bb12*fc00 + fc12;
            const double Lc03 = 3.0*Bb01*fc02 + 3.0*Bb02*fc01 + Bb03*fc00 + fc03;
            SC30 += pb * (3.0*Lc20 + Lc30*mu);
            SC21 += pb * (2.0*Lc11 + Lc21*mu);
