            const double Lx10 = Bb10*fx00 + fx10;
            const double Lx01 = Bb01*fx00 + fx01;
            const double Lx20 = 2.0*Bb10*fx10 + Bb20*fx00 + fx20;
            const double Lx11 = Bb01*fx10 + Bb10*fx01 + Bb11*fx00 + fx11;
            const double Lx02 = 2.0*Bb01*fx01 + Bb02*fx00 + fx02;
            const double Lx30 = 3.0*Bb10*fx20 + 3.0*Bb20*fx10 + Bb30*fx00 + fx30;
            const double Lx21 = Bb01*fx20 + 2.0*Bb10*fx11 + 2.0*Bb11*fx10 + Bb20*fx01 + Bb21*fx00 + fx21;
            const double Lx12 = 2.0*Bb01*fx11 + Bb02*fx10 + Bb10*fx02 + 2.0*Bb11*fx01 + Bb12*fx00 + fx12;
            const double Lx03 = 3.0*Bb01*fx02 + 3.0*Bb02*fx01 + Bb03*fx00 + fx03;
