            SX01 += pb * (Lx01*mu);
            SX20 += pb * (2.0*Lx10 + Lx20*mu);
            SX11 += pb * (Lx01 + Lx11*mu);
            SX02 += pb * (Lx02*mu);
            SX30 += pb * (3.0*Lx20 + Lx30*mu);
            SX21 += pb * (2.0*Lx11 + Lx21*mu);
